'use strict';

const retention = require('../../config/retention');

const MS_PER_DAY = 24 * 60 * 60 * 1000;

// Deletes customer exports older than the retention period.
//
// The retention period for customer exports has NOT been decided (see
// docs/retention.md and config/retention.js). Deletion from the store is
// permanent, so this function refuses to run unless it is given a decided
// period: either config.exportRetentionDays once compliance sets it, or an
// explicit retentionDays argument.
//
// Legal hold: docs/retention.md says some exports must never be deleted, but
// compliance has not said how to identify them and the store entries carry no
// such field. There is therefore no exemption rule here. Callers that purge
// real data must pass isExempt until that rule exists.
//
// Options:
//   store         - object with list()/remove(name); see src/exports/store.js
//   now           - Date to evaluate against (defaults to current time)
//   retentionDays - positive number of days; defaults to config value
//   isExempt      - optional (entry) => boolean; exempt entries are kept
//
// Returns { deleted: string[], kept: string[] }.
function purgeExpiredExports({ store, now = new Date(), retentionDays, isExempt } = {}) {
  if (!store || typeof store.list !== 'function' || typeof store.remove !== 'function') {
    throw new TypeError('purgeExpiredExports: store must provide list() and remove()');
  }
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('purgeExpiredExports: now must be a valid Date');
  }
  if (isExempt !== undefined && typeof isExempt !== 'function') {
    throw new TypeError('purgeExpiredExports: isExempt must be a function');
  }

  const days = retentionDays === undefined ? retention.exportRetentionDays : retentionDays;
  if (typeof days !== 'number' || !Number.isFinite(days) || days <= 0) {
    throw new Error(
      'purgeExpiredExports: no export retention period is set. Compliance has not ' +
        'decided one (config.exportRetentionDays is null; see docs/retention.md). ' +
        'Pass retentionDays explicitly to purge.'
    );
  }

  const cutoff = now.getTime() - days * MS_PER_DAY;
  const deleted = [];
  const kept = [];

  for (const entry of store.list()) {
    const createdAt = entry && entry.createdAt;
    // Anything we cannot date is kept: deletion is permanent.
    if (!(createdAt instanceof Date) || Number.isNaN(createdAt.getTime())) {
      kept.push(entry && entry.name);
      continue;
    }
    if (createdAt.getTime() >= cutoff || (isExempt && isExempt(entry))) {
      kept.push(entry.name);
      continue;
    }
    store.remove(entry.name);
    deleted.push(entry.name);
  }

  return { deleted, kept };
}

module.exports = { purgeExpiredExports, MS_PER_DAY };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { createMemoryStore } = require('../src/exports/store');
const { purgeExpiredExports, MS_PER_DAY } = require('../src/exports/purge');
const retention = require('../../config/retention') === undefined ? null : null; // placeholder

const NOW = new Date('2026-10-09T00:00:00Z');
const daysAgo = (n) => new Date(NOW.getTime() - n * MS_PER_DAY);

test('deletes only exports older than the retention period', () => {
  const store = createMemoryStore([
    { name: 'old.csv', createdAt: daysAgo(31) },
    { name: 'fresh.csv', createdAt: daysAgo(1) },
  ]);

  const result = purgeExpiredExports({ store, now: NOW, retentionDays: 30 });

  assert.deepEqual(result.deleted, ['old.csv']);
  assert.deepEqual(
    store.list().map((e) => e.name),
    ['fresh.csv']
  );
});

test('keeps an export exactly at the retention boundary', () => {
  const store = createMemoryStore([{ name: 'edge.csv', createdAt: daysAgo(30) }]);

  const result = purgeExpiredExports({ store, now: NOW, retentionDays: 30 });

  assert.deepEqual(result.deleted, []);
  assert.deepEqual(result.kept, ['edge.csv']);
});

test('refuses to purge when no retention period is configured', () => {
  const store = createMemoryStore([{ name: 'old.csv', createdAt: daysAgo(10000) }]);

  assert.throws(() => purgeExpiredExports({ store, now: NOW }), /no export retention period/);
  // Nothing was deleted; deletion is permanent.
  assert.deepEqual(
    store.list().map((e) => e.name),
    ['old.csv']
  );
});

test('rejects a non-positive or non-numeric retention period', () => {
  const store = createMemoryStore([{ name: 'old.csv', createdAt: daysAgo(100) }]);

  for (const bad of [0, -30, NaN, Infinity, '30', null]) {
    assert.throws(() => purgeExpiredExports({ store, now: NOW, retentionDays: bad }));
  }
  assert.equal(store.list().length, 1);
});

test('keeps entries the caller marks exempt', () => {
  const store = createMemoryStore([
    { name: 'held.csv', createdAt: daysAgo(400), legalHold: true },
    { name: 'plain.csv', createdAt: daysAgo(400) },
  ]);

  const result = purgeExpiredExports({
    store,
    now: NOW,
    retentionDays: 30,
    isExempt: (e) => e.legalHold === true,
  });

  assert.deepEqual(result.deleted, ['plain.csv']);
  assert.deepEqual(
    store.list().map((e) => e.name),
    ['held.csv']
  );
});

test('keeps entries with a missing or invalid createdAt', () => {
  const store = createMemoryStore([
    { name: 'nodate.csv' },
    { name: 'baddate.csv', createdAt: new Date('nope') },
  ]);

  const result = purgeExpiredExports({ store, now: NOW, retentionDays: 30 });

  assert.deepEqual(result.deleted, []);
  assert.equal(store.list().length, 2);
});

test('validates store and now', () => {
  const store = createMemoryStore([]);
  assert.throws(() => purgeExpiredExports({ retentionDays: 30 }), TypeError);
  assert.throws(() => purgeExpiredExports({ store: {}, retentionDays: 30 }), TypeError);
  assert.throws(
    () => purgeExpiredExports({ store, now: new Date('nope'), retentionDays: 30 }),
    TypeError
  );
  assert.throws(
    () => purgeExpiredExports({ store, now: NOW, retentionDays: 30, isExempt: 'yes' }),
    TypeError
  );
});

test('is a no-op on an empty store', () => {
  const store = createMemoryStore([]);
  const result = purgeExpiredExports({ store, now: NOW, retentionDays: 30 });
  assert.deepEqual(result, { deleted: [], kept: [] });
});

'use strict';

const retention = require('../../config/retention');

const MS_PER_DAY = 24 * 60 * 60 * 1000;

// Delete customer exports whose age exceeds the retention period.
//
// Deletion from the export store is permanent, and the retention period for
// customer exports has not been set by compliance (config.exportRetentionDays
// is null; see docs/retention.md). Rather than guess a number, this refuses to
// run until one is supplied. Likewise, some exports are under legal hold and
// must not be deleted; the caller must supply the predicate that identifies
// them, so that "no hold information available" can never silently mean
// "nothing is held".
//
//   store           - { list(), remove(name) }, see ./store.js
//   now             - Date, the instant to measure age against
//   retentionDays   - number > 0; defaults to config.exportRetentionDays
//   isOnLegalHold   - (entry) => boolean; required
//
// Returns { deleted: string[], retained: string[], held: string[] }.
function purgeExpiredExports({
  store,
  now,
  retentionDays = retention.exportRetentionDays,
  isOnLegalHold,
} = {}) {
  if (!store || typeof store.list !== 'function' || typeof store.remove !== 'function') {
    throw new TypeError('purgeExpiredExports: store must provide list() and remove()');
  }
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('purgeExpiredExports: now must be a valid Date');
  }
  if (typeof retentionDays !== 'number' || !Number.isFinite(retentionDays) || retentionDays <= 0) {
    throw new Error(
      'purgeExpiredExports: no export retention period is set. ' +
        'config.exportRetentionDays is pending a compliance decision (docs/retention.md); ' +
        'pass retentionDays explicitly to run a purge.'
    );
  }
  if (typeof isOnLegalHold !== 'function') {
    throw new Error(
      'purgeExpiredExports: isOnLegalHold predicate is required. ' +
        'Exports under legal hold must not be deleted and compliance has not yet ' +
        'specified how to identify them (docs/retention.md).'
    );
  }

  const cutoff = now.getTime() - retentionDays * MS_PER_DAY;
  const deleted = [];
  const retained = [];
  const held = [];

  for (const entry of store.list()) {
    const createdAt = entry.createdAt;
    // An entry we cannot age is an entry we cannot prove is expired: keep it.
    if (!(createdAt instanceof Date) || Number.isNaN(createdAt.getTime())) {
      retained.push(entry.name);
      continue;
    }
    if (createdAt.getTime() >= cutoff) {
      retained.push(entry.name);
      continue;
    }
    if (isOnLegalHold(entry)) {
      held.push(entry.name);
      continue;
    }
    store.remove(entry.name);
    deleted.push(entry.name);
  }

  return { deleted, retained, held };
}

module.exports = { purgeExpiredExports };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { createMemoryStore } = require('../src/exports/store');
const { purgeExpiredExports } = require('../src/exports/purge');

const NOW = new Date('2026-10-09T00:00:00Z');
const daysAgo = (n) => new Date(NOW.getTime() - n * 24 * 60 * 60 * 1000);
const noHold = () => false;

test('deletes exports older than the retention period', () => {
  const store = createMemoryStore([
    { name: 'old.csv', createdAt: daysAgo(31) },
    { name: 'fresh.csv', createdAt: daysAgo(2) },
  ]);

  const result = purgeExpiredExports({
    store,
    now: NOW,
    retentionDays: 30,
    isOnLegalHold: noHold,
  });

  assert.deepEqual(result.deleted, ['old.csv']);
  assert.deepEqual(result.retained, ['fresh.csv']);
  assert.deepEqual(
    store.list().map((e) => e.name),
    ['fresh.csv']
  );
});

test('an entry exactly at the retention boundary is kept', () => {
  const store = createMemoryStore([{ name: 'edge.csv', createdAt: daysAgo(30) }]);

  const result = purgeExpiredExports({
    store,
    now: NOW,
    retentionDays: 30,
    isOnLegalHold: noHold,
  });

  assert.deepEqual(result.deleted, []);
  assert.deepEqual(result.retained, ['edge.csv']);
  assert.equal(store.list().length, 1);
});

test('exports under legal hold are never deleted, however old', () => {
  const store = createMemoryStore([
    { name: 'held.csv', createdAt: daysAgo(900), hold: true },
    { name: 'old.csv', createdAt: daysAgo(900) },
  ]);

  const result = purgeExpiredExports({
    store,
    now: NOW,
    retentionDays: 30,
    isOnLegalHold: (e) => e.hold === true,
  });

  assert.deepEqual(result.held, ['held.csv']);
  assert.deepEqual(result.deleted, ['old.csv']);
  assert.deepEqual(
    store.list().map((e) => e.name),
    ['held.csv']
  );
});

test('entries with a missing or invalid createdAt are kept, not deleted', () => {
  const store = createMemoryStore([
    { name: 'no-date.csv' },
    { name: 'bad-date.csv', createdAt: new Date('nonsense') },
  ]);

  const result = purgeExpiredExports({
    store,
    now: NOW,
    retentionDays: 30,
    isOnLegalHold: noHold,
  });

  assert.deepEqual(result.deleted, []);
  assert.deepEqual(result.retained.sort(), ['bad-date.csv', 'no-date.csv']);
  assert.equal(store.list().length, 2);
});

test('refuses to purge when no retention period is configured', () => {
  const store = createMemoryStore([{ name: 'old.csv', createdAt: daysAgo(900) }]);

  // config.exportRetentionDays is null pending compliance, so the default path
  // must throw rather than fall back to some assumed number.
  assert.throws(
    () => purgeExpiredExports({ store, now: NOW, isOnLegalHold: noHold }),
    /no export retention period is set/
  );
  assert.equal(store.list().length, 1, 'nothing may be deleted on the error path');
});

test('refuses to purge without a legal-hold predicate', () => {
  const store = createMemoryStore([{ name: 'old.csv', createdAt: daysAgo(900) }]);

  assert.throws(
    () => purgeExpiredExports({ store, now: NOW, retentionDays: 30 }),
    /isOnLegalHold predicate is required/
  );
  assert.equal(store.list().length, 1, 'nothing may be deleted on the error path');
});

test('rejects a non-positive or non-numeric retention period', () => {
  const store = createMemoryStore([{ name: 'old.csv', createdAt: daysAgo(900) }]);

  for (const bad of [0, -30, '30', NaN, Infinity]) {
    assert.throws(
      () => purgeExpiredExports({ store, now: NOW, retentionDays: bad, isOnLegalHold: noHold }),
      /no export retention period is set/,
      `retentionDays=${String(bad)} must be rejected`
    );
  }
  assert.equal(store.list().length, 1);
});

test('rejects an invalid now', () => {
  const store = createMemoryStore([{ name: 'old.csv', createdAt: daysAgo(900) }]);

  assert.throws(
    () =>
      purgeExpiredExports({
        store,
        now: new Date('nonsense'),
        retentionDays: 30,
        isOnLegalHold: noHold,
      }),
    /now must be a valid Date/
  );
  assert.equal(store.list().length, 1);
});

test('rejects a store that does not implement the interface', () => {
  assert.throws(
    () => purgeExpiredExports({ store: {}, now: NOW, retentionDays: 30, isOnLegalHold: noHold }),
    /store must provide list\(\) and remove\(\)/
  );
});

test('purging an empty store is a no-op', () => {
  const store = createMemoryStore([]);

  const result = purgeExpiredExports({
    store,
    now: NOW,
    retentionDays: 30,
    isOnLegalHold: noHold,
  });

  assert.deepEqual(result, { deleted: [], retained: [], held: [] });
});

